   187  static void
   188  unscape_text(hoedown_buffer *ob, hoedown_buffer *src)
   189  {
   190          size_t i = 0, org;
   191          while (i < src->size) {
   192                  org = i;
   193                  while (i < src->size && src->data[i] != '\\')
   194                          i++;
   195
   196                  if (i > org)
   197                          hoedown_buffer_put(ob, src->data + org, i - org);
   198
   199                  if (i + 1 >= src->size)
   200                          break;
   201
   202                  hoedown_buffer_putc(ob, src->data[i + 1]);
   203                  i += 2;
   204          }
   205  }
